script:
frappe.ui.form.on('HSC Inhouse NP-ll', {

    onload(frm) {
        // hide only if not captured
        if (!frm.doc.latitude && !frm.doc.longitude) {
            frm.toggle_display('latitude', false);
            frm.toggle_display('longitude', false);
        } else {
            frm.toggle_display('latitude', true);
            frm.toggle_display('longitude', true);
        }
    },

    refresh(frm) {
        // keep visible if already saved
        if (frm.doc.latitude && frm.doc.longitude) {
            frm.toggle_display('latitude', true);
            frm.toggle_display('longitude', true);
        }
    },

    capture_location(frm) {

        if (!navigator.geolocation) {
            frappe.msgprint(__('Browser does not support location'));
            return;
        }

        frappe.dom.freeze(__('Fetching location...'));

        navigator.geolocation.getCurrentPosition(
            function (position) {

                frappe.dom.unfreeze();

                frm.set_value('latitude', position.coords.latitude);
                frm.set_value('longitude', position.coords.longitude);

                // show fields
                frm.toggle_display('latitude', true);
                frm.toggle_display('longitude', true);

                frappe.msgprint(__('Location captured successfully'));
            },
            function () {
                frappe.dom.unfreeze();
                frappe.msgprint(__('Please allow location access'));
            },
            {
                enableHighAccuracy: true,
                timeout: 10000
            }
        );
    }

});

frappe.ui.form.on("HSC Inhouse NP-II", {
    refresh: function(frm) {
        validate_all_id_fields(frm);
    },

    mobile_no: function(frm) {
        validate_digit_field(frm, "mobile_no", 10);
    },

    samagra_id: function(frm) {
        validate_digit_field(frm, "samagra_id", 9);
    },

    aadhar_number: function(frm) {
        validate_digit_field(frm, "aadhar_number", 12);
    },

    validate: function(frm) {
        validate_all_id_fields(frm);

        if (!is_valid_digit_field(frm, "mobile_no", 10)) {
            frappe.throw("Mobile No exactly 10 digit ka hona chahiye");
        }

        if (!is_valid_digit_field(frm, "samagra_id", 9)) {
            frappe.throw("Samagra ID exactly 9 digit ka hona chahiye");
        }

        if (!is_valid_digit_field(frm, "aadhar_number", 12)) {
            frappe.throw("Aadhar Number exactly 12 digit ka hona chahiye");
        }
    }
});

function validate_all_id_fields(frm) {
    validate_digit_field(frm, "mobile_no", 10);
    validate_digit_field(frm, "samagra_id", 9);
    validate_digit_field(frm, "aadhar_number", 12);
}

function validate_digit_field(frm, fieldname, exact_length) {
    let value = frm.doc[fieldname];

    if (!frm.fields_dict[fieldname]) {
        return;
    }

    let input = frm.fields_dict[fieldname].$input;

    if (!input) {
        return;
    }

    if (!value) {
        input.css({
            "border": "",
            "background-color": ""
        });
        return;
    }

    value = String(value).trim();

    if (!/^[0-9]+$/.test(value) || value.length !== exact_length) {
        input.css({
            "border": "2px solid red",
            "background-color": "#ffe6e6"
        });
    } else {
        input.css({
            "border": "",
            "background-color": ""
        });
    }
}

function is_valid_digit_field(frm, fieldname, exact_length) {
    let value = frm.doc[fieldname];

    if (!value) {
        return true;
    }

    value = String(value).trim();

    return /^[0-9]+$/.test(value) && value.length === exact_length;
}
